    {
      "rank": 1,
      "ballot_id": "B035",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks at 10^-18 precision are a major advance in measurement, enabling new tests of fundamental physics and applications such as relativistic geodesy.",
        "attribution": "Katori's lattice approach and Ye's independent advances in clock performance are central, complementary contributions.",
        "maturity": "The precision is supported by sustained experimental progress and independent clock comparisons; the technique is established and productive.",
        "uncertainties": ["The balance between credit for the original concepts, clock implementations, and later precision advances needs careful delineation."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": ["Juan Ignacio Cirac", "Peter Zoller", "Rainer Blatt"],
      "assessment": {
        "nobel_worthiness": "Trapped ions turned quantum information from an abstract proposal into a controllable experimental platform and enabled important quantum simulations and computations.",
        "attribution": "Cirac and Zoller supplied foundational theoretical proposals; Blatt established key experimental demonstrations with trapped ions.",
        "maturity": "The platform has decades of reproducible results and continues to advance, although large-scale fault-tolerant computation remains unfinished.",
        "uncertainties": ["The candidate combines several stages of progress, so the most defining contributions and their boundaries need to be specified."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B016",
      "proposed_laureates": ["Alexandre Blais", "Andreas Wallraff", "Robert J. Schoelkopf"],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics created a powerful way to couple and control artificial atoms with microwave photons, opening a major field in quantum optics and information.",
        "attribution": "Blais developed the key theoretical framework, while Wallraff and Schoelkopf led landmark experimental realizations and development of the platform.",
        "maturity": "The approach has been confirmed across many laboratories and underpins advanced quantum processors, though scalable fault tolerance is still in progress.",
        "uncertainties": ["The field's rapid development makes it difficult to separate the founding contributions from later engineering advances."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B014",
      "proposed_laureates": ["Eli Yablonovitch", "John D. Joannopoulos", "Sajeev John"],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and photonic band gaps established a general means of controlling light propagation and emission, with lasting influence across optics and photonics.",
        "attribution": "Yablonovitch and John made foundational proposals, while Joannopoulos helped develop the theory and its practical understanding.",
        "maturity": "The underlying effects are well established, and photonic crystal concepts have shaped decades of experimental and applied work.",
        "uncertainties": ["Credit among the independent early proposals and the subsequent theoretical and experimental development requires care."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B046",
      "proposed_laureates": ["Peter F. Moulton", "Ursula Keller", "Wilson Sibbett"],
      "assessment": {
        "nobel_worthiness": "The titanium-sapphire laser and practical femtosecond pulse generation transformed ultrafast science by making intense, tunable ultrashort pulses broadly accessible.",
        "attribution": "Moulton's titanium-sapphire laser and Keller's and Sibbett's mode-locking advances are distinct, consequential parts of the story.",
        "maturity": "The technologies have been extensively validated and used across physics and neighboring fields for decades.",
        "uncertainties": ["The candidate joins related but distinct laser and mode-locking innovations, and the attribution should reflect that distinction."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B022",
      "proposed_laureates": ["Christian J. Bordé", "David E. Pritchard", "Mark A. Kasevich"],
      "assessment": {
        "nobel_worthiness": "Atom interferometry brought matter-wave interference into precision measurement, enabling sensitive tests of fundamental physics and new quantum sensors.",
        "attribution": "Bordé and Pritchard made important early contributions to atom interferometry, and Kasevich demonstrated its power in precision measurements.",
        "maturity": "The method is well established, with a strong record of experimental use and continuing development in clocks, gravimetry, and fundamental tests.",
        "uncertainties": ["The broad scope spans several generations of instruments and applications, making the central discovery and appropriate credit difficult to delimit."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B049",
      "proposed_laureates": ["Alexei Kitaev", "Andrew M. Steane", "Peter W. Shor"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum information can, in principle, survive noise, changing the foundations and ambitions of quantum computing.",
        "attribution": "Shor and Steane introduced landmark error-correcting codes, while Kitaev's topological codes provided a distinct and influential route to fault tolerance.",
        "maturity": "The theory is firmly established, and experiments increasingly demonstrate error correction, but large-scale fault-tolerant operation remains unachieved.",
        "uncertainties": ["The candidate gathers several foundational ideas whose relative roles and experimental realization are not identical."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B026",
      "proposed_laureates": ["Ataç İmamoğlu", "Jörg Wrachtrup", "Ronald Hanson"],
      "assessment": {
        "nobel_worthiness": "Optical control and readout of solid-state spins, together with spin-photon entanglement, opened practical paths toward quantum networks and sensitive quantum measurements.",
        "attribution": "İmamoğlu contributed key optical interface concepts, Wrachtrup advanced optical control of solid-state spins, and Hanson demonstrated important spin-photon networking results.",
        "maturity": "Single-spin control and entanglement have strong experimental foundations, while robust, scalable network operation is still developing.",
        "uncertainties": ["This broad area includes several material platforms and milestones, so the proposed attribution may not capture all foundational contributions."]
      }
    }
  ]
}
